-- v8_026 · 2026-05-30 · 激活 DB 驱动 runtime tiers (方案A)
-- 由 scripts/gen_runtime_tiers_seed.py 从静态 manifest 快照生成 · 保证与静态一字不差
-- 安全阀: 出问题 `UPDATE v8_runtime_tiers SET enabled=FALSE` 即回退静态配置

-- 1) 建表(若 v8_024 未跑过) — 与 v8_024 同构
CREATE TABLE IF NOT EXISTS v8_runtime_tiers (
    id BIGSERIAL PRIMARY KEY,
    tier_name TEXT NOT NULL, display_name TEXT NOT NULL DEFAULT '', icon TEXT NOT NULL DEFAULT '',
    description TEXT NOT NULL DEFAULT '', task_types TEXT[] NOT NULL DEFAULT '{}', skills TEXT[] NOT NULL DEFAULT '{}',
    platform TEXT NOT NULL DEFAULT 'any', required BOOLEAN NOT NULL DEFAULT FALSE, auto_install BOOLEAN NOT NULL DEFAULT FALSE,
    enabled BOOLEAN NOT NULL DEFAULT TRUE, display_order INTEGER NOT NULL DEFAULT 0,
    source_type TEXT NOT NULL DEFAULT 'self_mirror',
    prebuilt_url TEXT NOT NULL DEFAULT '', prebuilt_sha256 TEXT NOT NULL DEFAULT '', prebuilt_size_mb FLOAT NOT NULL DEFAULT 0, prebuilt_version TEXT NOT NULL DEFAULT '',
    mirror_sources JSONB NOT NULL DEFAULT '[]',
    verify_cmd TEXT NOT NULL DEFAULT '', verify_timeout_secs INTEGER NOT NULL DEFAULT 60,
    packages TEXT[] NOT NULL DEFAULT '{}', depends_on TEXT[] NOT NULL DEFAULT '{}',
    requires_gpu BOOLEAN NOT NULL DEFAULT FALSE, requires_cuda BOOLEAN NOT NULL DEFAULT FALSE, requires_metal BOOLEAN NOT NULL DEFAULT FALSE,
    min_vram_gb FLOAT NOT NULL DEFAULT 0, min_ram_gb FLOAT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (tier_name, platform)
);
CREATE INDEX IF NOT EXISTS v8_runtime_tiers_enabled_idx ON v8_runtime_tiers (enabled, display_order);

-- 2) 补列(方案A 新增 · 静态配置里有但表里缺的) — 幂等
ALTER TABLE v8_runtime_tiers ADD COLUMN IF NOT EXISTS software TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE v8_runtime_tiers ADD COLUMN IF NOT EXISTS system_commands JSONB;
ALTER TABLE v8_runtime_tiers ADD COLUMN IF NOT EXISTS system_binaries JSONB;
ALTER TABLE v8_runtime_tiers ADD COLUMN IF NOT EXISTS install_hint JSONB;
ALTER TABLE v8_runtime_tiers ADD COLUMN IF NOT EXISTS pip_args TEXT[] NOT NULL DEFAULT '{}';

-- 3) Seed 7 tiers (platform='any' · 与静态 manifest 一致) — upsert 幂等
INSERT INTO v8_runtime_tiers (tier_name, display_name, icon, platform, display_order, description, required, auto_install, enabled, packages, software, task_types, skills, depends_on, verify_cmd, verify_timeout_secs, source_type, system_commands, system_binaries, install_hint) VALUES (
    'lite', '轻量运行环境', '📦', 'any', 1, '轻量运行环境: 图片/PDF/ONNX (不含音视频 · 见 ffmpeg tier)', TRUE, TRUE, TRUE, ARRAY['pillow','numpy','onnxruntime','PyMuPDF','pdfplumber']::text[], ARRAY['pillow','numpy','onnxruntime','pymupdf','pdfplumber']::text[], ARRAY['image_resize','image_compress','image_convert','image_thumbnail','image_info','onnx_infer','fft_compute','pdf_info','pdf_to_text']::text[], ARRAY['image-tools-v1','data-tools-v1','file-tools-v1','text-tools-v1','llm-tools-v1']::text[], '{}'::text[], 'import PIL, numpy, onnxruntime, fitz, pdfplumber; print(''lite ok'')', 60, 'self_mirror', NULL, NULL, NULL
) ON CONFLICT (tier_name, platform) DO UPDATE SET display_name=EXCLUDED.display_name, icon=EXCLUDED.icon, display_order=EXCLUDED.display_order, description=EXCLUDED.description, required=EXCLUDED.required, auto_install=EXCLUDED.auto_install, enabled=EXCLUDED.enabled, packages=EXCLUDED.packages, software=EXCLUDED.software, task_types=EXCLUDED.task_types, skills=EXCLUDED.skills, depends_on=EXCLUDED.depends_on, verify_cmd=EXCLUDED.verify_cmd, verify_timeout_secs=EXCLUDED.verify_timeout_secs, source_type=EXCLUDED.source_type, system_commands=EXCLUDED.system_commands, system_binaries=EXCLUDED.system_binaries, install_hint=EXCLUDED.install_hint, updated_at=NOW();

